<script setup lang="ts">
/**
 * Progress through an ordered flow (`design/components/stepper.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stepper.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/stepper.module.css'

export type StepperOrientation = NonNullable<StepperProps['orientation']>

export interface Step {
  label: string
  description?: string
  error?: boolean
}

export type StepperSpokenState = 'completed' | 'active' | 'upcoming' | 'error'

export type StepperSpoken = (step: {
  position: number
  count: number
  state: StepperSpokenState
}) => string

export interface StepperProps {
  /**
   * 0-based. Everything before it is completed, everything after it upcoming.
   */
  activeIndex: number
  orientation?: 'horizontal' | 'vertical'
  /**
   * Omit for the generic English sentence; localized hosts pass their own.
   */
  spoken?: StepperSpoken
  /**
   * Two to five; the spec says a flow with six steps needs a redesign.
   */
  steps: Step[]
}

defineOptions({ name: 'Stepper', inheritAttrs: false })

const props = withDefaults(defineProps<StepperProps>(), {
  orientation: 'horizontal',
  spoken: ({ position, count, state }: Parameters<StepperSpoken>[0]) =>
    `step ${position} of ${count}, ${{ completed: 'completed', active: 'current', upcoming: 'not started', error: 'error' }[state]}`,
})
const emit = defineEmits<{ stepSelect: [index: number] }>()
const listening = useListening()
const root = useTemplateRef<HTMLElement>('root')
const rows = computed(() =>
  props.steps.map((step, index) =>
    ((walk: 'completed' | 'active' | 'upcoming') => ({
      step,
      index,
      walk,
      state: step.error === true ? ('error' as const) : walk,
    }))(
      index < props.activeIndex ? 'completed' : index === props.activeIndex ? 'active' : 'upcoming',
    ),
  ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Stepper',
    element: () => root.value,
    state: () => ({
      'active-index': props.activeIndex,
      steps: rows.value.map((row) => ({ label: row.step.label, state: row.state })),
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!listening.stepSelect) throw new Error('These steps are not revisitable.')
            if (!Number.isInteger(value) || value < 0 || value >= props.activeIndex) {
              throw new Error(`Step ${value} is not a completed step, so it cannot be revisited.`)
            }
            emit('stepSelect', value)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <ol ref="root" :class="styles.root" :data-orientation="orientation" data-member="stepper">
    <template v-for="row in rows" :key="row.index">
      <!-- step -->
      <li
        :class="styles.step"
        :data-state="row.state"
        :data-interactive="row.walk === 'completed' && listening.stepSelect ? '' : undefined"
        :aria-current="row.walk === 'active' ? 'step' : undefined"
      >
        <!-- control -->
        <component
          :is="row.walk === 'completed' && listening.stepSelect ? 'button' : 'span'"
          :class="styles.control"
          :type="row.walk === 'completed' && listening.stepSelect ? 'button' : undefined"
          @click="row.walk === 'completed' && listening.stepSelect && emit('stepSelect', row.index)"
        >
          <!-- indicator -->
          <span :class="styles.indicator" aria-hidden="true">
            <Icon v-if="row.state === 'error'" name="error" size="sm" />
            <span v-else-if="row.state === 'completed'" :class="styles.check">
              <Icon name="confirm" size="sm" />
            </span>
            <template v-else>{{ row.index + 1 }}</template>
          </span>
          <!-- copy -->
          <span :class="styles.copy">
            <!-- label -->
            <span :class="styles.label">
              {{ row.step.label }}
            </span>
            <!-- description -->
            <span v-if="row.step.description !== undefined" :class="styles.description">
              {{ row.step.description }}
            </span>
            <!-- spoken -->
            <span :class="styles.spoken">
              {{
                `, ${spoken({ position: row.index + 1, count: steps.length, state: row.state })}`
              }}
            </span>
          </span>
        </component>
        <!-- connector -->
        <span
          v-if="row.index !== steps.length - 1"
          :class="styles.connector"
          :data-filled="row.walk === 'completed' ? '' : undefined"
        />
      </li>
    </template>
  </ol>
</template>
